(25,6,'III Jornada Acadêmica - Trabalhos Acadêmicos Premiados',NULL,'21 a 22 de Novembro de 2022',1,'certificado_3_jornada.jpg','\r\n		//código do template\r\n\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$trabalho = $certificado->titulo;\r\n		$outrosParticipantes = $certificado->outrosParticipantes;\r\n		$arquivo = \'Trabalho premiado - III Jornada - \'.$nome;\r\n\r\n		$pdf->AddPage($orientation=\'L\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(30);\r\n		$pdf->SetRightMargin(35);\r\n\r\n\r\n		// Set font\r\n		$font_pequena = \"14\";	\r\n		$font_media = \'13\';\r\n		$font_grande = \'30\';\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"70\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \"<p align=\'justify\'>Certificamos que o trabalho intitulado  <b>\".\'\"\'.strtoupper($trabalho).\'\"\'.\"</b> com autoria de <b>\".strtoupper($outrosParticipantes).\"</b> foi apresentado em formato online e premiado na III Jornada Acadêmica da Faculdade de Ciências Odontológicas (FCO) que ocorreu entre os dias 21 a 22 de Novembro de 2022.	</p>\";\r\n		\r\n\r\n		$pdf->WriteHTML(utf8_decode($s));\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
(26,2,'II Jornada FCO OnLine - Trabalhos Acadêmicos Premiados',NULL,'27 a 29 de Maio de 2021',1,'trabalhos_II_jornada_2021_data.jpg','//inicio codigo do template\r\n		\r\n		\r\n	$pdf = new Fpdf\\FPDF();\r\n\r\n	$pdf->AddPage($orientation=\'L\', $size=\'A4\');\r\n\r\n	$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n	$pdf->SetLeftMargin(60);\r\n	$pdf->SetRightMargin(30);\r\n\r\n	// Set font\r\n	$font_pequena = \"13\";	\r\n	$font_media = \'13\';\r\n	$font_grande = \'16\';\r\n\r\n	$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n	$nome = $certificado->outrosParticipantes;\r\n	$carga_horaria = $certificado->cargaHoraria.\' horas.\';\r\n	$trabalho = $certificado->titulo;\r\n	$arquivo = $certificado->arquivo;\r\n	$periodo = $certificado->periodo_atividade;\r\n	$nome_arquivo = $certificado->nome.\' - \'.\'certificado do trabalho academico premiado da II Jornada FCO\';\r\n	\r\n	$pdf->SetX(\"150\"); \r\n	$pdf->SetY(\"60\");\r\n	$pdf->MultiCell(0, 10, utf8_decode(\"Certificamos que o trabalho intitulado: \"),0,\'C\', false);\r\n	$pdf->SetFont(\'Arial\',\'B\',$font_media);\r\n	$pdf->MultiCell(0, 10, utf8_decode($trabalho),0,\'C\', false);\r\n	$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n	$pdf->MultiCell(0, 10, utf8_decode(\" com autoria de: \"),0,\'C\', false);\r\n	$pdf->SetFont(\'Arial\',\'B\',$font_media);\r\n	$pdf->MultiCell(0, 8, utf8_decode($nome),0,\'C\', false);\r\n	$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n	$pdf->MultiCell(0, 10, utf8_decode(\"foi premiado e apresentado em formato online entre os dias 27 a 29 de Maio durante a\"),0,\'C\', false);\r\n	$pdf->MultiCell(0, 10, utf8_decode(\"II Jornada Acadêmica da FCO - Faculdade de Ciências Odontológicas.\"),0,\'C\', false);\r\n	$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n	\r\n\r\n	// Set font\r\n	$pdf->SetFont(\'Arial\', \'\', $font_pequena);\r\n	\r\n	$pdf->MultiCell(0, 10, utf8_decode(\"\"),0,\'C\', false);		\r\n	//$pdf->MultiCell(0, 10, utf8_decode(\"Monte