(56,15,'Certificado de Membro da Liga LAOL',NULL,NULL,1,'fundo_laol_2023.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'lego - \'.$nome;\r\n		$cargaHoraria = $certificado->cargaHoraria;\r\n\r\n		if($cargaHoraria == 60) $cargaHoraria = \'60 (sessenta)\';\r\n		if($cargaHoraria == 80) $cargaHoraria = \'80 (oitenta)\';\r\n		if($cargaHoraria == 50) $cargaHoraria = \'50 (cinquenta)\';\r\n		\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"16\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"80\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que <b>\'.$nome.\'</b> participou das atividades da Liga Acadêmica de Odontologia Legal (LAOL), vinculada à Faculdade de Ciências Odontológicas (FCO), no período de 10 de julho de 2022 a 03 de agosto de 2023, com carga horária total equivalente a \'.$cargaHoraria.\' horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"125\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 31 de agosto de 2023\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
(57,15,'Certificado de Membro Fundador da Liga LAOL',NULL,NULL,1,'fundo_laol_2023.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'lego - \'.$nome;\r\n		$cargaHoraria = $certificado->cargaHoraria;\r\n		$cargo =  $certificado->titulo2;\r\n\r\n		if($cargaHoraria == 60) $cargaHoraria = \'60 (sessenta)\';\r\n		if($cargaHoraria == 80) $cargaHoraria = \'80 (oitenta)\';\r\n		if($cargaHoraria == 50) $cargaHoraria = \'50 (cinquenta)\';\r\n		\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"16\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"80\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que <b>\'.$nome.\'</b> atuou como \'.$cargo.\' e participou da fundação e das atividades da Liga Acadêmica de Odontologia Legal (LAOL), vinculada à Faculdade de Ciências Odontológicas(FCO), no período de 10 de julho de 2022 a 03 de agosto de 2023, com carga horária total equivalente a \'.$cargaHoraria.\' horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"125\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 31 de agosto de 2023\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
(58,16,'Certificado de Participante do Odonto Baby',NULL,NULL,1,'fundo_odontobaby_paisagem_2022.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'odontobaby - \'.$nome;\r\n		$cargaHoraria = $certificado->cargaHoraria;\r\n		$periodo = $certificado->titulo2;\r\n		$emissao = $certificado->titulo3;\r\n\r\n		if($cargaHoraria == 60) $cargaHoraria = \'60 sessenta)\';\r\n		if($cargaHoraria == 80) $cargaHoraria = \'80 (oitenta)\';\r\n		if($cargaHoraria == 100) $cargaHoraria = \'100 (cem)\';\r\n		if($cargaHoraria == 120) $cargaHoraria = \'120 (cento e vinte)\';\r\n		if($cargaHoraria == 200) $cargaHoraria = \'200 (duzentas)\';\r\n		\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"16\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"80\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que <b>\'.$nome.\'</b> participou do Programa de Extensão Odonto Baby, vinculado à Faculdade de Ciências Odontológicas (FCO), realizando atendimento odontológico em crianças nas clínicas odontológicas da FCO, em Montes Claros, MG, no período de \'.$periodo.\', cumprindo uma carga horária total de \'.$cargaHoraria.\' horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"125\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, $emissao\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
(59,17,'Certificado do Odonto Presente',NULL,NULL,1,'odonto_presente_2022.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'donto_presente - \'.$nome;\r\n		$cargaHoraria = $certificado->cargaHoraria;\r\n		$periodo = $certificado->titulo2;\r\n		$emissao = $certificado->titulo3;\r\n		\r\n		if($cargaHoraria == 40) $cargaHoraria = \'40 (quarenta)\';\r\n		if($cargaHoraria == 60) $cargaHoraria = \'60 (sessenta)\';\r\n		if($cargaHoraria == 80) $cargaHoraria = \'33 (trinta e três)\';\r\n		if($cargaHoraria == 100) $cargaHoraria = \'100 (cem)\';\r\n\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"16\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"75\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que <b>\'.$nome.\'</b> participou do Programa de Extensão Odonto Presente, vinculado à Faculdade de Ciências Odontológicas (FCO), realizando atendimento odontológico em pacientes oncológicos atendidos pela Associação Presente em Montes Claros, MG, no período de \'.$periodo.\', cumprindo uma carga horária total de \'.$cargaHoraria.\' horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"111\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, $emissao\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
