(69,24,'Certificado de Monitoria 2023',NULL,NULL,1,'monitoria.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'monitoria - \'.$nome;\r\n		$disciplina = $certificado->titulo2;\r\n		$periodo = $certificado->titulo3;\r\n		$professor = $certificado->outrosParticipantes;\r\n\r\n		$cargaHoraria = $certificado->cargaHoraria;\r\n\r\n		if($cargaHoraria == 60) $cargaHoraria = \'60 (sessenta)\';\r\n		if($cargaHoraria == 80) $cargaHoraria = \'80 (oitenta)\';\r\n		if($cargaHoraria == 50) $cargaHoraria = \'50 (cinquenta)\';\r\n		\r\n			\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"90\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que <b>\'.$nome.\'</b> exerceu atividade de Monitoria Voluntária referente à seguinte disciplina curricular: <b>\"\'.$disciplina.\'\"</b>, do curso de Odontologia da Faculdade de Ciências Odontológicas (FCO), no \'.$periodo.\', sob orientação \'.$professor.\', totalizando  \'.$cargaHoraria.\' horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"135\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 18 de dezembro de 2023\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
