(71,25,'Certificado do MIES V - 01/2023',NULL,'02 de dezembro de 2022',1,'mies.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'mies V - 1-2023 - \'.$nome;\r\n		$trabalho = $certificado->titulo2;\r\n		$nome_perceptor = $certificado->titulo3;\r\n		$alunos = $certificado->outrosParticipantes;\r\n		$sexo = $certificado->titulo4;\r\n		$pronome = ($sexo == \"m\") ? \"pelo preceptor \" : \"pela perceptora \";\r\n			\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"80\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que o trabalho intitulado <b>\"\'.$trabalho.\'\"</b> desenvolvido pelos acadêmicos <b>\'.$alunos.\'</b> e \'.$pronome.\'<b> \'.$nome_perceptor.\'</b>, orientado pela professora <b>Michelle Pimenta Oliveira</b> e <b>Patrícia e Helena Costa Mendes</b>, foi apresentado na forma de pôster, durante a V MOSTRA DE INTEGRAÇÃO ENSINO-SERVIÇO, realizada no dia 02 de dezembro de 2022 promovida pela Faculdade de Ciências Odontológicas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.6);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"155\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 30 de junho de 2023\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
