(82,30,'Certificado de presidente da Liga LASP',NULL,'15 de maio de 2023 a 13 de maio de 2024',1,'lasp_fundo.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'lasp 2023 fundacao - \'.$nome;\r\n		$periodo = $certificado->titulo2;\r\n	\r\n		$cargaHoraria = $certificado->cargaHoraria;\r\n\r\n		if($cargaHoraria == 60) $cargaHoraria = \'60 (sessenta)\';\r\n		if($cargaHoraria == 80) $cargaHoraria = \'80 (oitenta)\';\r\n		if($cargaHoraria == 50) $cargaHoraria = \'50 (cinquenta)\';\r\n		\r\n			\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"90\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que <b>\'.$nome.\'</b> atuou na fundação e como presidente nas atividades da Liga Acadêmica de Saúde Pública (LASP), vinculada à Faculdade de Ciências Odontológicas (FCO), no período de \'.$periodo.\', com carga horária total equivalente a \'.$cargaHoraria.\' horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"135\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 20 de maio de 2024\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
(83,31,'Certificado do MIES VII - 01/2024',NULL,'26 de junho de 2024',1,'mies.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'mies VII - 1-2024 - \'.$nome;\r\n		$trabalho = $certificado->titulo2;\r\n		$nome_perceptor = $certificado->titulo3;\r\n		$alunos = $certificado->outrosParticipantes;\r\n		$sexo = $certificado->titulo4;\r\n		$pronome = ($sexo == \"m\") ? \"pelo preceptor \" : \"pela perceptora \";\r\n			\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"80\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que o trabalho intitulado <b>\"\'.$trabalho.\'\"</b> desenvolvido pelos acadêmicos <b>\'.$alunos.\'</b> e \'.$pronome.\'<b> \'.$nome_perceptor.\'</b>, orientado pela professora <b>Michelle Pimenta Oliveira</b> e <b>Patrícia e Helena Costa Mendes</b>, foi apresentado na forma de pôster, durante a VII MOSTRA DE INTEGRAÇÃO ENSINO-SERVIÇO, realizada no dia 26 de junho de 2024, promovida pela Faculdade de Ciências Odontológicas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.5);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"155\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 26 de junho de 2024\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
(84,32,'Professor do Programa de Iniciação Científica',NULL,'1º de maio de 2023 a 30 de abril de 2024',1,'ic.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'ic_2023 - \'.$nome;\r\n		$professor = $nome;\r\n		$alunos = $certificado->outrosParticipantes;\r\n		$projeto =   $certificado->titulo3;\r\n		$sexo =   $certificado->titulo2;\r\n\r\n		if($sexo==\'m\') {\r\n			$titulosexo = \'do professor \';\r\n		} else {\r\n			$titulosexo = \'da professora \';\r\n		}\r\n						\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"16\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"75\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		\r\n		$s = \'<center>Certificamos que \'.$titulosexo.\'<b>\'.$professor.\'</b> participou nas atividades de pesquisa do Programa de Iniciação Científica, vinculado à Faculdade de Ciências Odontológicas (FCO), orientando os alunos \'.$alunos.\' no projeto de pesquisa intitulado \"<b>\'.$projeto.\'</b>\", no período de 1º de maio de 2023 a 30 de abril de 2024.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"125\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 30 de abril de 2023\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2026-05-27 18:23:23',NULL),
