(86,32,'Voluntário do Programa de Iniciação Científica',NULL,NULL,1,'ic.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'ic_2023 - \'.$nome;\r\n		$professor = $certificado->outrosParticipantes;\r\n		$projeto =   $certificado->titulo3;\r\n\r\n		$sexo =   $certificado->titulo2;\r\n\r\n		if($sexo==\'m\') {\r\n			$titulosexo = \' do professor \';\r\n		} else {\r\n			$titulosexo = \' da professora \';\r\n		}\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"16\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"75\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que <b>\'.$nome.\'</b> participou como voluntário nas atividades de pesquisa do Programa de Iniciação Científica, vinculado à Faculdade de Ciências Odontológicas (FCO), no projeto de pesquisa intitulado \"<b>\'.$projeto.\'</b>\", com orientação \'.$titulosexo.$professor.\', no período de 1º de maio de 2023 a 30 de abril de 2024.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"125\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 30 de abril de 2024\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
(87,20,'Certificado Odonto Presente 02/2024',NULL,'02 de maio de 2023 a 13 de março de 2024',1,'odonto_presente_sem_data_emissao.png','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'donto_presente 2024 - \'.$nome;\r\n		$cargaHoraria = $certificado->cargaHoraria;\r\n		$periodo = $certificado->titulo2;\r\n		$emissao = $certificado->titulo3;\r\n		\r\n		if($cargaHoraria == 40) $cargaHoraria = \'40 (quarenta)\';\r\n		if($cargaHoraria == 60) $cargaHoraria = \'60 (sessenta)\';\r\n		if($cargaHoraria == 80) $cargaHoraria = \'33 (trinta e três)\';\r\n		if($cargaHoraria == 100) $cargaHoraria = \'100 (cem)\';\r\n\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"16\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"75\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que <b>\'.$nome.\'</b> participou do Programa de Extensão Odonto Presente, vinculado à Faculdade de Ciências Odontológicas (FCO), realizando atendimento odontológico em pacientes oncológicos atendidos pela Associação Presente em Montes Claros, MG, no período de \'.$periodo.\', cumprindo uma carga horária total de \'.$cargaHoraria.\' horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"111\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, $emissao\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
(88,33,'Certificado Odonto Baby 2023',NULL,'25 agosto de 2023 a 21 junho de 2024',1,'fundo_odontobaby_paisagem_2022.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'odontobaby - \'.$nome;\r\n		$cargaHoraria = $certificado->cargaHoraria;\r\n		$periodo = $certificado->titulo2;\r\n		$emissao = $certificado->titulo3;\r\n\r\n		if($cargaHoraria == 60) $cargaHoraria = \'60 sessenta)\';\r\n		if($cargaHoraria == 80) $cargaHoraria = \'80 (oitenta)\';\r\n		if($cargaHoraria == 100) $cargaHoraria = \'100 (cem)\';\r\n		if($cargaHoraria == 120) $cargaHoraria = \'120 (cento e vinte)\';\r\n		if($cargaHoraria == 200) $cargaHoraria = \'200 (duzentas)\';\r\n		\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"16\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"80\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que <b>\'.$nome.\'</b> participou do Programa de Extensão Odonto Baby, vinculado à Faculdade de Ciências Odontológicas (FCO), realizando atendimento odontológico em crianças nas clínicas odontológicas da FCO, em Montes Claros, MG, no período de \'.$periodo.\', cumprindo uma carga horária total de \'.$cargaHoraria.\' horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"125\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, $emissao\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
(89,34,'Certificado do MIES IV - 02/2022',NULL,'08 de dezembro de 2022',1,'mies.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'mies IV - 2-2022 - \'.$nome;\r\n		$trabalho = $certificado->titulo2;\r\n		$nome_perceptor = $certificado->titulo3;\r\n		$alunos = $certificado->outrosParticipantes;\r\n		$sexo = $certificado->titulo4;\r\n		$pronome = ($sexo == \"m\") ? \"pelo preceptor \" : \"pela perceptora \";\r\n			\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"80\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que o trabalho intitulado <b>\"\'.$trabalho.\'\"</b> desenvolvido pelos acadêmicos <b>\'.$alunos.\'</b>, orientado pela professora <b>Michelle Pimenta Oliveira</b> e <b>Patrícia e Helena Costa Mendes</b>, foi apresentado na forma de pôster, durante a IV MOSTRA DE INTEGRAÇÃO ENSINO-SERVIÇO, realizada no dia 08 de dezembro de 2022, promovida pela Faculdade de Ciências Odontológicas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.5);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"155\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 08 de dezembro de 2022\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
(90,35,'Certificado de Participação na Semana do Estudante Dia 06 de Agosto de 2024',NULL,'06 de agosto de 2024',1,'semana_estudante.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'semana_estudante_2.2024_\'.$nome;\r\n		$tema = $certificado->titulo2;\r\n		$periodo = $certificado->titulo3;\r\n		$emissao = $certificado->titulo3;\r\n			\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(45);\r\n		$pdf->SetRightMargin(45);\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"80\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certifico que <s><b>\'.$nome.\'</b></s> participou da palestra <b>\"\'.$tema.\'\"</b>, no dia \'.$periodo.\', durante a Semana de Recepção dos Estudantes 2.2024 da Faculdade de Ciências Odontológicas (FCO), com carga horária de duas horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.5);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"130\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\'Montes Claros, \'.$emissao.\'\'),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-16 13:37:02',NULL),
