(95,38,'Uso de flúor e controle de cárie: derrubando fake news',NULL,'13 de novembro de 2024',1,'fundo_atividade_115.png','//código do template\r\n\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$palestra = \'Uso de flúor e controle de cárie: derrubando fake news\';\r\n		$professor = \"Jaime Cury\"; \r\n		$arquivo = \'Palestra Online - \'.$nome;\r\n\r\n		$pdf->AddPage($orientation=\'L\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(42);\r\n		$pdf->SetRightMargin(35);\r\n\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n		\r\n		$pdf->SetX(\"45\"); \r\n		$pdf->SetY(\"60\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \"Certificamos que <b>\".strtoupper($nome).\"</b> participou da palestra <br/> <b>\".\'\"\'.strtoupper($palestra).\'\"\'.\"</b> ministrada pelo professor <b>\".$professor.\"</b>  em formato online, durante a IV Jornada Acadêmica da Faculdade de Ciências Odontológica (FCO), realizada nos dia 13 e  14 de Novembro de 2024, com carga horária  de <b>2 horas</b>. \";\r\n\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.5);\r\n		$pdf->SetLeftMargin(95);\r\n		$pdf->SetY(\"127\");\r\n		$d = \"Montes Claros, 14 de novembro de 2024\";\r\n		$pdf->WriteHTML(utf8_decode($d),\'Arial\',1.5);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-16 12:40:27','2025-02-19 16:29:31',NULL),
