(121,40,'Monitoria Voluntária 2023',NULL,'2023',1,'monitoria.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'Monitoria Voluntária - \'.$nome;\r\n		$disciplina = $certificado->titulo2;\r\n		$orientador = $certificado->titulo3;\r\n		$periodo = $certificado->titulo4;\r\n		$cargaHoraria = $certificado->cargaHoraria;\r\n		\r\n		if($cargaHoraria == 120) $cargaHoraria = \'120 (cento e vinte)\';\r\n		if($cargaHoraria == 100) $cargaHoraria = \'100 (cem)\';\r\n		if($cargaHoraria == 50) $cargaHoraria = \'50 (cinquenta)\';\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"80\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que o(a) acadêmico(a) <b>\"\'.$nome.\'\"</b> exerceu atividade de Monitoria Voluntária referente à disciplina curricular <b>\"\'.$disciplina.\'\"</b> do curso de Odontologia da Faculdade de Ciências Odontológicas (FCO), no <b>\"\'.$periodo.\'\"</b>, sob orientação do(a) Prof.(a) <b>\"\'.$orientador.\'\"</b>, totalizando <b>\'.$cargaHoraria.\'</b> horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.5);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"155\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 16 de dezembro de 2024\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-18 16:13:58','2025-02-18 20:12:19',NULL),
(122,41,'Certificados da Apresentação de Trabalhos MIES VIII',NULL,'30 de novembro de 2024',1,'mies.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'mies VIII - 2-2024 - \'.$nome;\r\n		$trabalho = $certificado->titulo;\r\n		$orientadores = $certificado->titulo3;\r\n		$alunos = $certificado->outrosParticipantes;\r\n			\r\n				\r\n		$pdf->AddPage($orientation=\'L\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"80\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que o trabalho intitulado <b>\"\'.$trabalho.\'\"</b> desenvolvido pelos acadêmicos <b>\'.$alunos.\'</b>, orientado pela professora <b>Michelle Pimenta Oliveira</b> e <b>Patrícia Helena Costa Mendes</b>, foi apresentado na forma de pôster, durante a VI MOSTRA DE INTEGRAÇÃO ENSINO-SERVIÇO, realizada no dia 30 de novembro de 2024, promovida pela Faculdade de Ciências Odontológicas.</center>\';\r\n		\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.5,\'J\');\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"155\");\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 30 de novembro de 2024\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-02-20 17:54:16','2025-02-20 22:08:44',NULL),
(123,42,'Certificado de Participante da Liga LACBI',NULL,'',1,'fundo_atividade_123.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'LACBI - membro - \'.$nome;\r\n		$cargaHoraria = $certificado->cargaHoraria;\r\n		$periodo = $certificado->titulo4;\r\n		$funcao = $certificado->titulo3;\r\n\r\n		if($cargaHoraria == 60) $cargaHoraria = \'60 (sessenta)\';\r\n		if($cargaHoraria == 80) $cargaHoraria = \'80 (oitenta)\';\r\n		if($cargaHoraria == 50) $cargaHoraria = \'50 (cinquenta)\';\r\n		\r\n			\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"90\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que <b>\'.$nome.\'</b> participou como \'.$funcao.\' da Liga Acadêmica de Cirurgia Bucomaxilofacial e Implantodontia (LACBI), vinculada à Faculdade de Ciências Odontológicas (FCO), no  período de <b>\'.$periodo.\'</b>, com carga horária total equivalente a \'.$cargaHoraria.\' horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"130\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 6 de março de 2025\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-03-06 20:36:54','2025-03-12 17:42:30',NULL),
