(129,47,'Mincurso - Inovação em Cirurgia Bucomaxilofacial Impressão 3D e Tecnologias Digitais',NULL,'23 e 24 de outubro de 2025',1,'fundo_atividade_129.png','//código do template\r\n\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$palestra = \'Inovação em Cirurgia Bucomaxilofacial Impressão 3D e Tecnologias Digitais\';\r\n		$professor = \"Prof. Ms. Lucas Augusto Pereira Souto\"; \r\n		$arquivo = \'Plestra_Inovacao - \'.$nome;\r\n\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(42);\r\n		$pdf->SetRightMargin(35);\r\n\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n	\r\n		$pdf->SetX(\"45\"); \r\n		$pdf->SetY(\"60\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \"<center>Certificamos que <b>\".strtoupper($nome).\"</b> participou do Minicurso <br/> <b>\".\'\"\'.strtoupper($palestra).\'\"\'.\"</b> ministrada pelo <b>\".$professor.\"</b>  durante a V Jornada Odontológica da Faculdade de Ciências Odontológica (FCO), realizada nos dias 23 e 14 de Novembro de 2025, com carga horária  de <b>2 horas</b>. </center>\";\r\n\r\n\r\n		\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.5);\r\n		$pdf->SetLeftMargin(95);\r\n		$pdf->SetY(\"127\");\r\n		$d = \"Montes Claros, 24 de novembro de 2025\";\r\n		$pdf->WriteHTML(utf8_decode($d),\'Arial\',1.5);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-11-13 15:40:38','2025-12-01 17:15:25',NULL),
