(150,47,'Coordenador de Comissão da V Jornada',NULL,'23 e 24 de outubro de 2025',1,'fundo_atividade_149.png','//código do template\r\n\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$sexo = $certificado->titulo2;\r\n		$arquivo = strtoupper(\'Avaliadores V Jornada - \'.$nome);\r\n		$termo = ($sexo == \"M\") ? \"COORDENADOR\" : \"COORDENADORA\"; \r\n\r\n		$pdf->AddPage($orientation=\'L\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(42);\r\n		$pdf->SetRightMargin(35);\r\n\r\n\r\n		// Set font\r\n		$font_pequena = \"18\";	\r\n		\r\n\r\n		$pdf->SetX(\"45\"); \r\n		$pdf->SetY(\"60\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \"Certificamos que <b>\".strtoupper($nome).\"</b> atuou como \".$termo.\" da comissão científica na V Jornada Odontológica da Faculdade de Ciências Odontológica (FCO), realizada nos dias <b>23 e  24 de outubro de 2025<b/>.\";\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.5);\r\n		$pdf->SetLeftMargin(95);\r\n		$pdf->SetY(\"127\");\r\n		$d = \"Montes Claros, 24 de outubro de 2025\";\r\n		$pdf->WriteHTML(utf8_decode($d),\'Arial\',1.5);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-12-03 20:36:40','2025-12-05 16:23:44',NULL),
(151,10,' Certificado de Membro da Liga LEGO 2024',NULL,'23/08/2025 as 06/06/2025',1,'fundo_atividade_151.jpg','//código do template\r\n		$this->load->library(\'PDF_HTML\');\r\n		$pdf = $this->pdf = new PDF_HTML();\r\n\r\n		//variaveis\r\n		$nome = $certificado->participante;\r\n		$arquivo = \'lego - \'.$nome;\r\n		$cargaHoraria = $certificado->cargaHoraria;\r\n		\r\n				\r\n		$pdf->AddPage($orientation=\'J\', $size=\'A4\');\r\n		$pdf->Image(FCPATH.\'/uploads/certificados/\'.$certificado->imagemFundo,0,0,297,0,\'\',\'\');\r\n		$pdf->SetLeftMargin(35);\r\n		$pdf->SetRightMargin(35);\r\n\r\n		// Set font\r\n		$font_pequena = \"16\";	\r\n		\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"80\");\r\n\r\n		$pdf->SetFont(\'Arial\',\'\',$font_pequena);\r\n\r\n		$s = \'<center>Certificamos que <b>\'.$nome.\'</b> participou das atividades da Liga Acadêmica de Empreendedorismo e Gestão em Odontologia (LEGO), vinculada à Faculdade de Ciências Odontológicas, no período de 23 de agosto de 2024 a 06 de junho 2025, com carga horária total equivalente a \'.$cargaHoraria.\' horas.</center>\';\r\n\r\n\r\n		$pdf->WriteHTML(utf8_decode($s),\'Arial\',1.3);\r\n\r\n		$pdf->SetX(\"40\"); \r\n		$pdf->SetY(\"125\");\r\n\r\n		$pdf->MultiCell(0, 10, utf8_decode(\"Montes Claros, 06 de junho de 2025\"),0,\'C\', false);\r\n\r\n		header(\'Content-Type: application/pdf\');\r\n		$pdf->SetAuthor(\'FCO\');\r\n		$pdf->Output(\'I\',$arquivo); // I D F S\r\n		//template fim ','2025-12-18 17:25:01','2025-12-18 17:28:34',NULL),
